import{_ as e,c as r,o as i,ah as t}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"6、【訟】 坎下乾上","description":"橫渠易說 - 6、【訟】 坎下乾上","frontmatter":{"title":"6、【訟】 坎下乾上","description":"橫渠易說 - 6、【訟】 坎下乾上"},"headers":[],"relativePath":"classics/hengqu/008.md","filePath":"classics/hengqu/008.md"}'),h={name:"classics/hengqu/008.md"};function l(n,a,s,c,d,o){return i(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="_6、【訟】-坎下乾上" tabindex="-1">6、【訟】 坎下乾上 <a class="header-anchor" href="#_6、【訟】-坎下乾上" aria-label="Permalink to “6、【訟】 坎下乾上”">​</a></h1><p>彖曰：訟，上剛下險，險而健訟。“訟有孚窒惕中吉”，剛來而得中也。“終兇”，訟不可成也。“利見大人”，尚中正也；“不利涉大川”，入於淵也。</p><h3 id="象曰-天與水違行-訟-君子以作事謀始。" tabindex="-1">象曰：天與水違行，訟，君子以作事謀始。 <a class="header-anchor" href="#象曰-天與水違行-訟-君子以作事謀始。" aria-label="Permalink to “象曰：天與水違行，訟，君子以作事謀始。”">​</a></h3><h3 id="初六-不永所事-小有言-終吉。-象曰-不永所事-訟不可長也。雖小有言-其辨明也。" tabindex="-1">初六，不永所事，小有言，終吉。 象曰：“不永所事”，訟不可長也。雖小有言，其辨明也。 <a class="header-anchor" href="#初六-不永所事-小有言-終吉。-象曰-不永所事-訟不可長也。雖小有言-其辨明也。" aria-label="Permalink to “初六，不永所事，小有言，終吉。 象曰：“不永所事”，訟不可長也。雖小有言，其辨明也。”">​</a></h3><p>初於正應，中有陰陽之間，不無訟。但以陰居下體為柔順，履險方初，不永所事，其理辨直，故小有言終吉。直一作正。</p><h3 id="九二-不克訟-歸而逋其邑人三百戶-無眚。-象曰-不克訟-歸逋竄也。自下訟上-患至掇也。" tabindex="-1">九二，不克訟，歸而逋其邑人三百戶，無眚。 象曰：“不克訟”，歸逋竄也。自下訟上，患至掇也。 <a class="header-anchor" href="#九二-不克訟-歸而逋其邑人三百戶-無眚。-象曰-不克訟-歸逋竄也。自下訟上-患至掇也。" aria-label="Permalink to “九二，不克訟，歸而逋其邑人三百戶，無眚。 象曰：“不克訟”，歸逋竄也。自下訟上，患至掇也。”">​</a></h3><p>處險體剛，好訟者也，上下二陰俱非己應，理為不直，故不訟。歸而逋竄；使其邑人之眾無辜被禍，故曰“邑人無眚”。</p><h3 id="六三-食舊德-貞厲-終吉。或從王事無成。-象曰-食舊德-從上吉也。" tabindex="-1">六三，食舊德，貞厲，終吉。或從王事無成。 象曰：“食舊德”，從上吉也。 <a class="header-anchor" href="#六三-食舊德-貞厲-終吉。或從王事無成。-象曰-食舊德-從上吉也。" aria-label="Permalink to “六三，食舊德，貞厲，終吉。或從王事無成。 象曰：“食舊德”，從上吉也。”">​</a></h3><p>履非其位，處險之極，若能不為他累，專應上九，則雖危終吉，故曰“舊德”；以陰居陽，又處成功，必有悔吝，故曰“無成”。</p><h3 id="九四-不克訟-復即命渝-安貞吉。-象曰-復即命渝-安貞不失也。" tabindex="-1">九四，不克訟，復即命渝，安貞吉。 象曰：“復即命渝”，安貞不失也。 <a class="header-anchor" href="#九四-不克訟-復即命渝-安貞吉。-象曰-復即命渝-安貞不失也。" aria-label="Permalink to “九四，不克訟，復即命渝，安貞吉。 象曰：“復即命渝”，安貞不失也。”">​</a></h3><h3 id="九五-訟元吉。-象曰-訟元吉-以中正也。" tabindex="-1">九五，訟元吉。 象曰：“訟元吉”，以中正也。 <a class="header-anchor" href="#九五-訟元吉。-象曰-訟元吉-以中正也。" aria-label="Permalink to “九五，訟元吉。 象曰：“訟元吉”，以中正也。”">​</a></h3><h3 id="上九-或錫之鞶帶-終朝三褫之。-象曰-以訟受服-亦不足敬也。" tabindex="-1">上九，或錫之鞶帶，終朝三褫之。 象曰：以訟受服，亦不足敬也。 <a class="header-anchor" href="#上九-或錫之鞶帶-終朝三褫之。-象曰-以訟受服-亦不足敬也。" aria-label="Permalink to “上九，或錫之鞶帶，終朝三褫之。 象曰：以訟受服，亦不足敬也。”">​</a></h3><p>體健而比於三，理為不直，故不克訟。</p>',13)])])}const m=e(h,[["render",l]]);export{p as __pageData,m as default};
